import cellxgene_census, collections, time
with cellxgene_census.open_soma() as census:
    obs=census['census_data']['homo_sapiens'].obs
    counts={}
    t=time.time(); batches=0
    reader=obs.read(column_names=['dataset_id','donor_id'])
    for tbl in reader:
        df=tbl.to_pandas()
        g=df.groupby('dataset_id').agg(n_cells=('donor_id','size'))
        for dsid,row in g.iterrows():
            if dsid not in counts:
                counts[dsid]=[0,set()]
            counts[dsid][0]+=int(row.n_cells)
            uniq=set(df.loc[df.dataset_id==dsid,'donor_id'])
            counts[dsid][1].update(uniq)
        batches+=1
        if batches%20==0: print('batches',batches,'rows',batches*len(df),'datasets',len(counts),'elapsed',round(time.time()-t,1))
    print('done datasets',len(counts))
    for dsid,(n,uset) in counts.items():
        if len(uset)==33 or n==279633:
            print('candidate',dsid,'cells',n,'donors',len(uset),'sample',list(uset)[:10])
