    value = str(value)
    try:
        return (0, int(value))
    except ValueError:
        return (1, value)


def as_dense_vector(matrix):
    if sp.issparse(matrix):
        return np.asarray(matrix).ravel()
    return np.asarray(matrix).ravel()


